def html_tela(a):
    lg=a['tema'] in('Papéis de categoria','Os números do varejo')
    corpo=f'<div class="au-g lg"><p class="au-d" style="font-size:21px;max-width:1240px">{a["defi"]}</p><div>{a["info"]}</div><div class="au-q"><b>{I("loja")} Na Divina Terra</b>{a["aqui"]}</div></div>' if lg else f'<div class="au-g"><div><p class="au-d">{a["defi"]}</p><div class="au-q"><b>{I("loja")} Na Divina Terra</b>{a["aqui"]}</div></div><div>{a["info"]}</div></div>'
    capn={'1':'(1) Para onde vamos','3':'(3) Como vamos'}[a['ch']];et={'1':'2','3':'4'}[a['ch']]
    return f'<section class="tela s-au" data-titulo="Para entender: {a["tema"]}" data-cap="{capn}" data-etapa="{et}" data-fala="{a["fala"]}">\n<span class="eb">{I("aula")} Para entender · {a["tema"]}</span><h2 style="font-size:44px">{a["h2"]}</h2>{corpo}<p class="fonte">Fonte: {a["fonte"]}</p>\n</section>\n'
def aplicar(t):
    import re
    for a in A:
        m=re.search(r'<section[^>]*data-titulo="'+re.escape(a['antes'])+'"',t)
        if not m: print('sem alvo',a['antes']);continue
        t=t[:m.start()]+html_tela(a)+t[m.start():]
    return t
